package ru.apokali4.aptechnayasmena

data class DrugMonograph(val id:String,val name:String,val inn:String,val description:String,val group:String,val indications:String,val contraindications:String,val adverseEffects:String,val pharmacodynamics:String,val pharmacokinetics:String,val forms:String,val source:String,val sourceUrl:String)

val drugCatalog = listOf(
DrugMonograph("paracetamol","Парацетамол","Paracetamol · ATX N02BE01","Ненаркотический анальгетик и антипиретик. Снижает боль и повышенную температуру; выраженное периферическое противовоспалительное действие нехарактерно.","Анальгетики и антипиретики; анилиды.","Симптоматическое лечение боли слабой и умеренной интенсивности и лихорадки. Возрастные ограничения и длительность зависят от конкретной формы и инструкции.","Гиперчувствительность к компонентам; тяжёлая печёночная недостаточность или активное тяжёлое заболевание печени. При хроническом употреблении алкоголя, недостаточном питании, обезвоживании и заболеваниях печени требуется особая осторожность.","Возможны аллергические реакции, кожная сыпь, тошнота и другие реакции ЖКТ; редко описаны нарушения со стороны крови и тяжёлые кожные реакции. Передозировка может вызвать тяжёлое поражение печени.","Обладает обезболивающим и жаропонижающим действием. Механизм полностью не установлен; связывают с подавлением синтеза простагландинов преимущественно в ЦНС и влиянием на центры боли и терморегуляции. Противовоспалительное действие слабое.","После приёма внутрь быстро всасывается преимущественно в тонкой кишке; Cmax обычно достигается примерно через 0,5–2 часа в зависимости от формы. Метаболизируется главным образом в печени путём конъюгации; метаболиты выводятся преимущественно почками.","Таблетки, порошки/гранулы, суспензии, суппозитории и растворы для инфузий в зависимости от производителя.","Инструкция по медицинскому применению парацетамола, таблетки; ЛС ГЭОТАР.","https://www.lsgeotar.ru/drugs/paracetamol-ABSp"),
DrugMonograph("ibuprofen","Ибупрофен","Ibuprofen · ATX M01AE01","Нестероидный противовоспалительный препарат, производное пропионовой кислоты. Обладает обезболивающим, жаропонижающим и противовоспалительным действием.","НПВП; производные пропионовой кислоты.","Симптоматическое лечение боли и воспаления, включая некоторые мышечно-суставные и ревматические состояния, невралгии, головную и зубную боль, болезненные менструации и лихорадку. Точный перечень зависит от формы и дозировки.","Гиперчувствительность к ибупрофену/НПВП; бронхоспазм или крапивница после ацетилсалициловой кислоты/других НПВП; активная язва или кровотечение ЖКТ; тяжёлая сердечная, печёночная или почечная недостаточность; третий триместр беременности. Полный перечень зависит от инструкции.","Возможны диспепсия, боль в животе, тошнота, диарея или запор, головная боль, головокружение и сыпь. Значимые риски: язва и кровотечение ЖКТ, бронхоспазм, задержка жидкости, повышение давления, ухудшение функции почек и тяжёлая аллергия.","Неизбирательно и обратимо ингибирует ЦОГ‑1 и ЦОГ‑2, снижая синтез простагландинов — медиаторов боли, воспаления и лихорадки. Обратимо влияет на агрегацию тромбоцитов.","После приёма внутрь хорошо всасывается из ЖКТ. Пища может замедлять всасывание. Более 90% связывается с белками плазмы; метаболизируется преимущественно в печени, метаболиты выводятся главным образом почками. Период полувыведения обычно около 2 часов.","Таблетки/капсулы, суспензии для приёма внутрь, гели и мази; риски и ограничения различаются для системного и местного применения.","Инструкции по медицинскому применению ибупрофена; RLS/Vidal.","https://www.rlsnet.ru/drugs/ibuprofen-1365"),
DrugMonograph("amoxicillin","Амоксициллин","Amoxicillin · ATX J01CA04","Полусинтетический β‑лактамный антибиотик пенициллинового ряда. Применяется при определённых бактериальных инфекциях; не действует на вирусы.","Бета-лактамные антибактериальные препараты; пенициллины.","Инфекции, вызванные чувствительными микроорганизмами. Конкретные показания зависят от инструкции, локализации инфекции и чувствительности возбудителя. Не предназначен для самолечения простуды или вирусного кашля.","Аллергия на амоксициллин, другие пенициллины или тяжёлая немедленная реакция на другие β‑лактамы. Дополнительные ограничения и коррекция при нарушении функции почек определяются инструкцией и врачом.","Часто отмечаются диарея, тошнота и кожная сыпь. Возможны рвота, кандидоз, аллергические реакции вплоть до анафилаксии, антибиотик-ассоциированный колит и изменения лабораторных показателей.","Бактерицидный антибиотик. Связывается с пенициллин-связывающими белками и нарушает синтез пептидогликана клеточной стенки бактерий, что приводит к гибели чувствительных микроорганизмов.","После приёма внутрь быстро и хорошо всасывается; пища обычно существенно не снижает всасывание. Распределяется в тканях и жидкостях. Значительная доля выводится почками в неизменённом виде; при снижении функции почек выведение замедляется.","Капсулы, таблетки, диспергируемые таблетки и порошки для приготовления суспензии; наличие зависит от производителя.","Инструкция по медицинскому применению амоксициллина, капсулы; материалы производителя.","https://nizhpharm.ru/upload/iblock/b45/olwg53291jfgnieum048p44t451n6x91/Amoksitsillin-kapsuly_LV_040723.pdf")
)

fun validateDrugCatalog(items:List<DrugMonograph>):List<String> {
 val errors=mutableListOf<String>(); val ids=mutableSetOf<String>()
 items.forEach { d -> if(d.id.isBlank() || !ids.add(d.id)) errors += "Пустой или повторяющийся id: ${'$'}{d.id}"; listOf(d.name,d.inn,d.description,d.group,d.indications,d.contraindications,d.adverseEffects,d.pharmacodynamics,d.pharmacokinetics,d.forms,d.source,d.sourceUrl).forEachIndexed { i,v -> if(v.isBlank()) errors += "${'$'}{d.id}: пустое поле ${'$'}i" } }
 return errors
}